def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = set(v for row in grid for v in row)

    for color in colors:
        cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        while cells:
            start = cells.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for q in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if q in cells:
                        cells.remove(q)
                        comp.add(q)
                        stack.append(q)

            r0 = min(r for r, c in comp)
            r1 = max(r for r, c in comp)
            c0 = min(c for r, c in comp)
            c1 = max(c for r, c in comp)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            border = {
                (r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                if r in (r0, r1) or c in (c0, c1)
            }
            if comp == border:
                inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
                fill = 2 if inner_h % 2 == 0 and inner_w % 2 == 0 else 7
                for r in range(r0 + 1, r1):
                    for c in range(c0 + 1, c1):
                        out[r][c] = fill

    return out
